input.content:
:root {
  --bg-1: #050b18;
  --bg-2: #0e1d36;
  --panel: rgba(15, 22, 38, 0.8);
  --panel-strong: rgba(12, 17, 29, 0.93);
  --card: rgba(17, 28, 46, 0.88);
  --line: rgba(142, 220, 255, 0.28);
  --text: #edf5ff;
  --muted: #9ab1ce;
  --accent: #7ee7ff;
  --accent-2: #8d7bff;
  --good: #8ef0b8;
  --warn: #ffd770;
  --danger: #ff7f96;
  --shadow: rgba(0, 0, 0, 0.35);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  min-height: 100%;
  background:
    radial-gradient(circle at top, rgba(43, 96, 164, 0.35), transparent 40%),
    linear-gradient(160deg, var(--bg-1), var(--bg-2) 60%, #0b1022 100%);
  color: var(--text);
  font-family: 'Inter', sans-serif;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 20px;
}

button {
  font: inherit;
}

.stars {
  position: fixed;
  inset: 0;
  background-image:
    radial-gradient(2px 2px at 10% 20%, rgba(255,255,255,0.9), transparent 100%),
    radial-gradient(1.5px 1.5px at 30% 70%, rgba(126,231,255,0.8), transparent 100%),
    radial-gradient(2.2px 2.2px at 70% 30%, rgba(180,165,255,0.9), transparent 100%),
    radial-gradient(1.5px 1.5px at 80% 80%, rgba(255,255,255,0.8), transparent 100%),
    radial-gradient(1.8px 1.8px at 90% 15%, rgba(255,220,140,0.7), transparent 100%);
  background-size: 220px 220px;
  opacity: 0.8;
  pointer-events: none;
}

.hud-wrap {
  position: relative;
  z-index: 1;
  width: min(1200px, 100%);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 14px 18px;
  background: rgba(11, 18, 30, 0.82);
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: 0 12px 40px var(--shadow);
}

.eyebrow {
  margin: 0;
  color: var(--accent);
  letter-spacing: 0.16em;
  font-size: 0.7rem;
  text-transform: uppercase;
}

h1 {
  margin: 8px 0 0;
  font-family: 'Orbitron', sans-serif;
  font-size: clamp(1.5rem, 3vw, 2.7rem);
}

.ghost-btn {
  border: 1px solid rgba(126, 231, 255, 0.5);
  background: rgba(18, 33, 58, 0.9);
  color: var(--text);
  border-radius: 999px;
  padding: 0.8rem 1.2rem;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.ghost-btn:hover { transform: translateY(-1px); box-shadow: 0 0 18px rgba(126,231,255,0.2); }

.game-shell {
  display: grid;
  grid-template-columns: minmax(260px, 300px) minmax(0, 1fr);
  gap: 18px;
  min-height: 680px;
}

.status-panel,
.story-panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 22px;
  box-shadow: 0 22px 40px rgba(0,0,0,0.25);
}

.status-panel {
  padding: 18px 16px;
}

.status-panel h2,
.fleet-box h3 {
  margin: 0 0 12px;
  font-family: 'Orbitron', sans-serif;
  font-size: 1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.stat-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-bottom: 18px;
}

.stat-card {
  background: rgba(18, 30, 48, 0.8);
  border: 1px solid rgba(142,220,255,0.18);
  border-radius: 12px;
  padding: 10px 12px;
}

.stat-label {
  display: block;
  font-size: 0.68rem;
  color: var(--muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.stat-value {
  font-size: 1.2rem;
  font-weight: 700;
  font-family: 'Orbitron', sans-serif;
}

.fleet-box {
  background: rgba(11, 19, 31, 0.8);
  border-radius: 14px;
  border: 1px solid var(--line);
  padding: 12px 14px;
}

#logList {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

#logList li {
  position: relative;
  padding-left: 12px;
  color: var(--muted);
  font-size: 0.9rem;
  line-height: 1.5;
}

#logList li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: var(--accent);
}

.story-panel {
  padding: 18px;
}

.scene-card {
  height: 100%;
  min-height: 620px;
  background: linear-gradient(180deg, rgba(12,20,31,0.93), rgba(8,12,20,0.9));
  border-radius: 18px;
  border: 1px solid rgba(142,220,255,0.18);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.scene-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px 10px;
  border-bottom: 1px solid rgba(142,220,255,0.12);
}

.scene-top h2 {
  margin: 0;
  font-family: 'Orbitron', sans-serif;
  font-size: clamp(1.2rem, 2vw, 1.8rem);
}

.scene-badge {
  border-radius: 999px;
  padding: 0.45rem 0.75rem;
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  border: 1px solid rgba(142,220,255,0.26);
  background: rgba(126,231,255,0.08);
  color: var(--accent);
}

.scene-body {
  display: grid;
  grid-template-columns: 1.2fr 0.8fr;
  gap: 16px;
  padding: 18px;
  min-height: 0;
  flex: 1;
}

.story-copy {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.story-copy p {
  margin: 0;
  color: var(--text);
  line-height: 1.7;
  font-size: 1.04rem;
}

.story-copy p strong { color: var(--accent); }

.choice-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 8px;
}

.choice-btn {
  width: 100%;
  text-align: left;
  padding: 15px 16px;
  border-radius: 14px;
  border: 1px solid rgba(142,220,255,0.25);
  background: rgba(20, 34, 52, 0.9);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.choice-btn:hover {
  transform: translateY(-1px);
  border-color: rgba(126,231,255,0.55);
  box-shadow: 0 0 16px rgba(126,231,255,0.15);
}

.choice-btn:disabled {
  opacity: 0.7;
  cursor: default;
}

.choice-btn .choice-tag {
  display: inline-block;
  margin-bottom: 8px;
  font-size: 0.68rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent);
}

.choice-btn strong {
  display: block;
  font-size: 1rem;
  line-height: 1.4;
}

.side-panel {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.mission-box,
.outcome-box {
  background: rgba(10, 18, 30, 0.8);
  border: 1px solid rgba(142,220,255,0.14);
  border-radius: 16px;
  padding: 16px;
}

.mission-box h3,
.outcome-box h3 {
  margin: 0 0 12px;
  font-family: 'Orbitron', sans-serif;
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
}

.mission-box p,
.outcome-box p {
  margin: 0;
  line-height: 1.6;
  color: var(--muted);
}

.outcome-box.good { border-color: rgba(142,240,184,0.35); }
.outcome-box.warn { border-color: rgba(255,215,112,0.35); }
.outcome-box.danger { border-color: rgba(255,127,150,0.35); }

.outcome-box.good p { color: var(--good); }
.outcome-box.warn p { color: var(--warn); }
.outcome-box.danger p { color: var(--danger); }

@media (max-width: 880px) {
  body { padding: 12px; }
  .topbar { padding: 12px 14px; }
  .game-shell { grid-template-columns: 1fr; }
  .scene-body { grid-template-columns: 1fr; }
  .scene-card { min-height: 540px; }
}

@media (max-width: 520px) {
  .topbar { align-items: flex-start; }
  .stat-grid { grid-template-columns: 1fr 1fr; }
  .scene-top { align-items: flex-start; flex-direction: column; }
  .scene-badge { align-self: flex-start; }
}

