  await page.screenshot({ path: '/tmp/opencode/starlance-mobile.jpg', type: 'jpeg', quality: 72, fullPage: true });
  const overflow = await page.evaluate(() => ({ scroll: document.documentElement.scrollWidth, client: document.documentElement.clientWidth }));
  assert(overflow.scroll <= overflow.client, `mobile horizontal overflow ${JSON.stringify(overflow)}`);
  assert(errors.length === 0, `browser errors: ${errors.join('; ')}`);
  console.log(JSON.stringify({ result: 'passed', repAfterEpisode, mobile: overflow, screenshot: '/tmp/opencode/starlance-mobile.jpg' }));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
